// ---- story (chapter Ch9, ch9 agent 2026-10-07; Sapphire data/maps/MossdeepCity_House1/scripts.inc; generators must keep
// everything from this line on; entries above marked "// story:"). Scripts 2-3, text lines 1-8 (line 0 is the generator's).
// People (data/story/ch9.json, uid = Sapphire local id): the Black Belt 1, his wife 2. Room tiles = Sapphire tiles + (1, 1).
// The Black Belt tells which Pokéblock the lead Pokémon likes (GetPokeblockNameByMonNature: the flavor of its nature, Gen 3's
// compatibility table = the nature's raised stat: Attack Red, Defense Yellow, Speed Pink, Sp. Atk Blue, Sp. Def Green; a
// nature whose raised and lowered stat are the same likes nothing). Black 2 has no Pokéblocks, so the line names the
// colour with the Pokéblock's Sapphire name written into one line per colour (text lines 3-7), as the strings of
// Sapphire's ContestStatsText_*PokeBlock; the nature is Black 2's (PokePartyGetParam field 112, as 0870.s).
#include "scenes/ch9_lib.inc"
#define T_HmmYourPokemon 1
#define T_Neutral 2
#define T_LikesRed 3                    // by the nature's raised stat 0-4: Red, Yellow, Pink, Blue, Green
#define T_LikesYellow 4
#define T_LikesPink 5
#define T_LikesBlue 6
#define T_LikesGreen 7
#define T_Husband 8

HB_BlackBelt:                           // MossdeepCity_House1_EventScript_BlackBelt
    c9_talk
    WorkSetConst C9_A, 0
    WorkSetConst C9_B, 0
    PokePartyGetMemberByType C9_A, 2    // bufferleadmonspeciesname 0
    PokePartyGetParam C9_B, C9_A, 112   // the lead's nature (0 Hardy ... 24 Quirky, Gen 3's order)
    WordSetPartyPokeSpecies 1, C9_A
#ifdef HOENN_TEST_CH9N
    WorkSetConst C9_B, HOENN_TEST_CH9N          // test builds only (HOENN_TEST_CH9N=<nature>): a chosen nature
#endif
    h_msgbox T_HmmYourPokemon           // Hmm! Your {STR_VAR_1}...
    WorkSet C9_C, C9_B
    WorkDiv C9_C, 5                     // the raised stat
    WorkSet C9_D, C9_B
    WorkMod C9_D, 5                     // the lowered stat
    h_goto_if_eq_var C9_C, C9_D, L_HB_Neutral
    h_goto_if_eq C9_C, 0, L_HB_Red
    h_goto_if_eq C9_C, 1, L_HB_Yellow
    h_goto_if_eq C9_C, 2, L_HB_Pink
    h_goto_if_eq C9_C, 3, L_HB_Blue
    h_msgbox T_LikesGreen             // It likes Green Pokéblocks, doesn't it? No, I'm positive of it! ...
    h_release
L_HB_Red:
    h_msgbox T_LikesRed
    h_release
L_HB_Yellow:
    h_msgbox T_LikesYellow
    h_release
L_HB_Pink:
    h_msgbox T_LikesPink
    h_release
L_HB_Blue:
    h_msgbox T_LikesBlue
    h_release
L_HB_Neutral:                           // MossdeepCity_House1_EventScript_NeutralNature
    h_msgbox T_Neutral                  // It doesn't appear to like or dislike any Pokéblocks.
    h_release

HB_Woman:                               // MossdeepCity_House1_EventScript_Woman
